def apply(Y, EN):
    by = {y["slug"]: y for y in Y}
    for slug, b in BOOST.items():
        if slug not in by: print("seo_boost: unknown slug", slug); continue
        by[slug]["faq"] = list(by[slug]["faq"]) + b["hi"]
        EN[slug]["faq"] = list(EN[slug]["faq"]) + b["en"]
